med <- function(x, m, n) {
  v <- x$`Median (s)`[x$Method == m & x$n == n]
  if (length(v) == 0) NA_real_ else v[1]
}
mem <- function(x, m, n) {
  v <- x$`Memory (MB)`[x$Method == m & x$n == n]
  if (length(v) == 0) NA_real_ else v[1]
}
speedup <- function(x, m, n) med(x, m, n) / med(x, "fastsae", n)
